import sys,pathlib,json,tempfile,dataclasses,hashlib
ROOT=pathlib.Path('/Users/lanxingcan/Workspace/zstdoxize');sys.path.insert(0,str(ROOT/'scripts'))
import check_greedy_interop_recipes as checker
attempts=[]
def audit(event,args):
 if event in ('subprocess.Popen','os.system','os.fork','os.posix_spawn','os.exec','os.spawn'):
  attempts.append(event);raise RuntimeError('child process forbidden')
sys.addaudithook(audit)
value=checker.check()
from oracles import greedy_interop as gen,double_fast_interop as prior
controls=[]
def rejects(label,action):
 try:action()
 except (ValueError,OSError):controls.append(label)
 else:raise ValueError('accepted '+label)
base=prior.Recipe('control',b'abcd',(4,14,6,6,1,4,0,3,0))
for name,value in [('name',''),('name','../escape'),('source',bytearray(b'x')),('source',bytes(gen.MAX_SOURCE+1)),('request',[4,14,6,6,1,4,0,3,0]),('request',(4,14,6,6,1,4,0,True,0)),('expected','advanced'),('origin','')]:
 rejects('record-'+name+'-'+type(value).__name__,lambda:dataclasses.replace(base,**{name:value}).metadata())
for index,limits in enumerate([(10,31),(6,30),(6,30),(1,30),(3,7),(0,131072),(3,3)],start=1):
 for bad in (limits[0]-1,limits[1]+1,True):
  values=list(base.request);values[index]=bad
  rejects('scalar-'+str(index)+'-'+str(bad),lambda:gen.selected_greedy_status(4,tuple(values)))
for size in (-1,gen.MAX_SOURCE+1,True):
 rejects('size-'+str(size),lambda:gen.selected_greedy_status(size,base.request))
with tempfile.TemporaryDirectory(prefix='zstdoxide-greedy-public-input-') as d:
 root=pathlib.Path(d);original=checker.MANIFEST.read_bytes()
 for name,change in [('count',lambda v:v.update(recipe_count=True)),('source',lambda v:v['recipes'][0].update(source_sha256='0'*64)),('status',lambda v:v['recipes'][0].update(expected='resource')),('equivalence',lambda v:v['expected_rust_frame_equivalence'].pop())]:
  v=checker.decode(original);change(v);p=root/(name+'.json');p.write_text(json.dumps(v));rejects('manifest-'+name,lambda:checker.check(p))
 p=root/'linked.json';p.symlink_to(checker.MANIFEST);rejects('linked-manifest',lambda:checker.check(p))
 for data in (b'{"a":1,"a":2}',b'{"x":NaN}'):
  rejects('json-'+data.decode(),lambda:checker.decode(data))
checker.require(not attempts,'no children')
print(json.dumps({'optimized':not __debug__,'manifest_sha256':hashlib.sha256(checker.MANIFEST.read_bytes()).hexdigest(),'controls':controls,'child_attempts':len(attempts)},sort_keys=True,indent=2))
